// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.junit.jupiter.api.Test;

class InvocationAggregateObservationTest {

	@Test
	void d101ConstantPerOpenPredictionsAreSummed() {
		BindingSetAssignment node = trackedNode();
		node.setDoubleMetricPlanned("optimizer.costEventRows", 2.0d);

		for (int open = 0; open < 49_800; open++) {
			EvaluationStatistics.beginInvocationObservation(node);
			close(node, 2L, EvaluationStatistics.TerminationClassification.EXHAUSTED);
		}

		EvaluationStatistics.InvocationAggregateObservation observation = EvaluationStatistics
				.invocationAggregateObservation(node, true);
		assertEquals(99_600.0d, observation.rawPredictedRowsSum());
		assertEquals(99_600.0d, observation.appliedPredictedRowsSum());
		assertEquals(99_600.0d, observation.actualRowsSum());
		assertEquals(49_800L, observation.opens());
		assertEquals(49_800L, observation.exhaustedOpens());
		assertTrue(observation.exactLogicalCardinality());
	}

	@Test
	void d102VaryingPerOpenPredictionsAreSummed() {
		BindingSetAssignment node = trackedNode();
		for (long prediction : new long[] { 1L, 10L, 100L }) {
			node.setDoubleMetricPlanned("optimizer.costEventRows", prediction);
			EvaluationStatistics.beginInvocationObservation(node);
			close(node, prediction, EvaluationStatistics.TerminationClassification.EXHAUSTED);
		}

		EvaluationStatistics.InvocationAggregateObservation observation = EvaluationStatistics
				.invocationAggregateObservation(node, true);
		assertEquals(111.0d, observation.rawPredictedRowsSum());
		assertEquals(111.0d, observation.appliedPredictedRowsSum());
		assertEquals(111.0d, observation.actualRowsSum());
	}

	@Test
	void d103ExistsHitIsCensoredFirstMatchEvidence() {
		EvaluationStatistics.SemiAntiOutcomeObservation observation = semiAntiObservation(
				1L, 0L, 7L, 0L, EvaluationStatistics.TerminationClassification.EARLY_SUCCESS, true);

		assertEquals(1L, observation.matchedRows());
		assertEquals(7L, observation.firstMatchWork());
		assertEquals(0L, observation.exhaustionWork());
		assertEquals(EvaluationStatistics.TerminationClassification.EARLY_SUCCESS,
				observation.terminationClassification());
	}

	@Test
	void d104ExistsMissIsExhaustedZeroEvidence() {
		EvaluationStatistics.SemiAntiOutcomeObservation observation = semiAntiObservation(
				0L, 1L, 0L, 31L, EvaluationStatistics.TerminationClassification.EXHAUSTED, true);

		assertEquals(0L, observation.matchedRows());
		assertEquals(1L, observation.unmatchedRows());
		assertEquals(31L, observation.exhaustionWork());
		assertTrue(observation.rootCompleted());
	}

	@Test
	void d105PartialCancelledAndFailedOpensAreDiagnosticOnly() {
		for (EvaluationStatistics.TerminationClassification termination : new EvaluationStatistics.TerminationClassification[] {
				EvaluationStatistics.TerminationClassification.PARTIAL,
				EvaluationStatistics.TerminationClassification.CANCELLED,
				EvaluationStatistics.TerminationClassification.FAILED }) {
			BindingSetAssignment node = trackedNode();
			node.setDoubleMetricPlanned("optimizer.costEventRows", 10.0d);
			EvaluationStatistics.beginInvocationObservation(node);
			close(node, 3L, termination);

			EvaluationStatistics.InvocationAggregateObservation observation = EvaluationStatistics
					.invocationAggregateObservation(node, true);
			assertFalse(observation.exactLogicalCardinality(), termination.name());
			assertFalse(observation.admissiblePhysicalWork(), termination.name());
		}
	}

	@Test
	void d106ProbeExposureNeverBecomesSampleMultiplicity() {
		BindingSetAssignment node = trackedNode();
		node.setDoubleMetricPlanned("optimizer.costEventRows", 0.0d);
		for (int open = 0; open < 100_000; open++) {
			EvaluationStatistics.beginInvocationObservation(node);
			close(node, 0L, EvaluationStatistics.TerminationClassification.EXHAUSTED);
		}

		EvaluationStatistics.InvocationAggregateObservation observation = EvaluationStatistics
				.invocationAggregateObservation(node, true);
		assertEquals(100_000L, observation.opens());
		assertEquals(1L, observation.statisticalSampleWeight());
	}

	private static BindingSetAssignment trackedNode() {
		BindingSetAssignment node = new BindingSetAssignment();
		node.setCostFeedbackTrackingEnabled(true);
		return node;
	}

	private static void close(BindingSetAssignment node, long rows,
			EvaluationStatistics.TerminationClassification termination) {
		EvaluationStatistics.closeInvocationObservation(node, rows, rows, -1L, -1L, -1L, -1L, -1L, -1L,
				-1L, -1L, termination);
	}

	private static EvaluationStatistics.SemiAntiOutcomeObservation semiAntiObservation(long matched, long unmatched,
			long firstMatchWork, long exhaustionWork, EvaluationStatistics.TerminationClassification termination,
			boolean rootCompleted) {
		long outer = matched + unmatched;
		return new EvaluationStatistics.SemiAntiOutcomeObservation("EXISTS", "streaming-correlated",
				"streaming-correlated", outer, matched, unmatched, outer, matched, unmatched, 0L,
				firstMatchWork + exhaustionWork, unmatched, outer, 0L, 0L, 0L, true, "", "", 1.0d,
				1.0d, firstMatchWork, exhaustionWork, 0L, outer, 0L, outer, termination, rootCompleted);
	}
}
